// Explorations shown on the site. Media for each lives in public/explorations/<slug>/
// (index.html = live visualizer, preview.mp4 = card loop, poster.jpg = card still),
// generated by `node visualizers/publish.mjs`.

export type Song = {
  title: string;
  artist: string;
  spotifyId: string; // open.spotify.com/track/<id>
  cover: string; // album art (from Spotify oEmbed)
  note: string; // why it pairs with the visual
};

export type Exploration = {
  slug: string;
  title: string;
  kind: string;
  year: string;
  blurb: string; // one line on the card
  concept: string; // a short paragraph on the visualizer page
  accent: string; // glow colour for hover / active states
  songs: Song[];
};

const art = (hash: string) => `https://i.scdn.co/image/${hash}`;

